        for channel in [UInt8(0), UInt8(255)] {
            let bytes = Data([channel, 0, 255, 255])
            let provider = CGDataProvider(data: bytes as CFData)!
            let image = CGImage(width: 1, height: 1, bitsPerComponent: 8, bitsPerPixel: 32, bytesPerRow: 4, space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGBitmapInfo(rawValue: CGImageAlphaInfo.last.rawValue), provider: provider, decode: nil, shouldInterpolate: false, intent: .defaultIntent)!
