        }
        precondition(CGImageDestinationFinalize(destination))
        let source = CGImageSourceCreateWithData(data, nil)!
        precondition(CGImageSourceGetType(source) as String? == "com.compuserve.gif")
        precondition(CGImageSourceGetCount(source) == 2)
        for index in 0..<2 {
            precondition(CGImageSourceCreateThumbnailAtIndex(source, index, [kCGImageSourceCreateThumbnailFromImageAlways: true, kCGImageSourceThumbnailMaxPixelSize: 64] as CFDictionary) != nil)
        }
        print("PASS real generated GIF signature, two frames and bounded ImageIO decode (synthetic fixture, not live-site acceptance)")
